// Only explicitly saved plans participate in guide calculations.
function wbEffective(c,r=routeContext(c)){try{const p=wbProjectValidate(wbApplied[c.id]),key=p.lanes[r]?r:!wbAvailable(c.id).includes(r)?p.continuationRoute:null;if(!key)return null;const full=p.lanes[key];if(wbPlanIssues(full).length)return null;const early=wbSplitPlan(full).early,d=r==='summary'||r==='救世篇'?full:{...full,stages:early};return d.stages.length?{p,r:key,d,full}:null;}catch{return null;}}
wbCharacterPlan=function(c,r){const effective=wbEffective(c,r),allowed=wbAvailable(c.id),key=allowed.includes(r)?r:allowed[0];return effective?{draft:effective.d,r:effective.r,custom:true}:{draft:wbPreset(c.id,key),r:key,custom:false};};
const originalProfileBuild=profileBuild,originalFinalBuild=finalBuild,originalInitialPlan=initialPlan,originalSkillTargets=skillTargets;
function wbCustomBuild(c,r){const e=wbEffective(c,r);if(!e)return null;const rows=wbCalculate(e.d).rows,pick=level=>rows.find(x=>x.end>level)||rows.at(-1),last=wbClass(e.d.stages.at(-1).classId),base=originalProfileBuild(c,r);return {...base,mid:[pick(20).className],upper:[pick(35).className],end:last.cn,focus:last.allowedSkills.join(' / '),priority:'按已保存的职业路线与等级培养。',goals:[requirement(wbClass(pick(20).className)),requirement(wbClass(pick(35).className))]};}
profileBuild=function(c,r){return wbCustomBuild(c,r)||originalProfileBuild(c,r);};
finalBuild=function(c){return wbCustomBuild(c,'summary')||originalFinalBuild(c);};
initialPlan=function(c,b){const e=wbEffective(c);if(!e)return originalInitialPlan(c,b);const cl=wbClass(e.d.stages.find(s=>Number(wbClass(s.classId).col_31)>=5)?.classId||e.d.stages[0].classId);return {name:cl.cn,skip:e.d.level>=20,reason:'按已保存的入队等级接续。'};};
function wbRecommendedClass(c,r){const e=wbEffective(c,r);return e?wbClass(e.d.stages.at(-1).classId).cn:null;}
skillTargets=function(c){if(c.canUseArenaTraining===false)return [];const e=wbEffective(c);if(!e)return originalSkillTargets(c);const goal=new Map(),good=c.good.split(':').map(skillName);for(const s of e.d.stages){const cl=wbClass(s.classId);for(const [skill,rank] of [...cl.must,...(cl.any.length?[cl.any.find(([name])=>good.includes(name))||cl.any[0]]:[])])if(!goal.has(skill)||rankValue(rank)>rankValue(goal.get(skill).rank))goal.set(skill,{rank,cl:cl.cn});}return [...goal].map(([skill,v])=>({skill,...v}));};
// Character cards retain their original four-stage layout and shared hover links.
// The original cardCareer function was defined in v9.js; restore that component.
cardCareer=function(c,b=buildPlan(c)){if(c.canChangeClass===false)return `<div class="card-career-modern"><div class="card-career-label"><span>职业养成方向</span><b>固定职业</b></div><ol class="mini-career-track first-part-track"><li><span class="mini-step"><small>第三部</small></span><div class="mini-career-options">${referenceLink('class',wbClass(c.startClass).id,c.startClass)}</div></li></ol></div>`;const early=initialPlan(c,b),third=routeContext(c)==='summary'||routeContext(c)==='救世篇',stages=[['初级',early.skip?'无需回练':early.name],['中级',b.mid[0]],['上级',b.upper[0]],...(third?[['第三部',b.end.split(' / ')[0]]]:[])];return `<div class="card-career-modern"><div class="card-career-label"><span>职业养成方向</span><b>${wbEffective(c)?'已应用自定义':esc(profileName(c))}</b></div><ol class="mini-career-track ${third?'':'first-part-track'}">${stages.map(([label,name],i)=>`<li class="${i===0&&early.skip?'skipped-stage':''}"><span class="mini-step"><i>${i+1}</i><small>${label}</small></span>${name==='无需回练'?`<b>${name}</b>`:`<div class="mini-career-options"><span class="mini-career-choice primary-choice"><button class="mini-career-link" data-reference-type="class" data-reference-id="${escapeAttr(name)}">${classIcon(wbClass(name),28)}<span>${esc(name)}</span></button></span></div>`}</li>`).join('')}</ol></div>`;};
const careerDirectionSelection={};
function careerBand(cl){return cl.cn!=='舞者'&&wbThirdOnlyClass(cl)?'third':cl.col_1;}
function careerDirections(c,r){const base=wbPreset(c.id,r),plans=CATALOG.careerAlternatives?.[c.id]||[],out=[{name:'推荐 · '+profileName(c,r),d:base,when:'',stop:''}];for(const p of plans){const bands=new Map();for(const name of p.classes){const cl=wbClass(name);if(!cl)continue;const band=careerBand(cl);if(!bands.has(band))bands.set(band,[]);if(!bands.get(band).includes(name))bands.get(band).push(name);}let variants=[[]];for(const names of bands.values())variants=variants.flatMap(v=>names.map(name=>[...v,name]));for(const names of variants){const d=wbValidate(base);for(const name of names){const cl=wbClass(name);if(cl.cn==='舞者'&&c.id!=='c7'){const at=d.stages.findIndex(s=>s.phase==='third');if(at>=0){const upper=d.stages.find(s=>s.phase==='early'&&wbClass(s.classId).col_1==='上级职业');if(upper){upper.classId=wbClass('侍道').id;upper.reason='第三部接舞位前，以剑系资格与速度接续；按实际需要停止升级。';}d.stages.splice(at,0,{...d.stages[at],classId:cl.id,levels:0,reason:'第三部取得舞者资格后接舞位；前期仅蕾达可转职。',phase:'third'});}continue;}const band=careerBand(cl),at=d.stages.findIndex(s=>careerBand(wbClass(s.classId))===band);if(at>=0){d.stages[at].classId=cl.id;d.stages[at].phase=wbThirdOnlyClass(cl,c)?'third':d.stages[at].phase;d.stages[at].reason=p.title+'：'+p.when+' '+p.stop;}}out.push({name:p.title.replace('备选','方向')+(variants.length>1?' · '+names.filter(n=>bands.get(careerBand(wbClass(n))).length>1).join(' / '):''),d:wbValidate(d),when:p.when,stop:p.stop,source:p.source});}}return out;}

let wbInline=null;
function wbDetailRoute(c){const context=routeContext(c),effective=wbEffective(c,'summary'),r=wbAvailable(c.id).includes(context)?context:effective?.r||wbAvailable(c.id)[0],key=c.id,directions=careerDirections(c,r),chosen=directions[careerDirectionSelection[key]||0]||directions[0],useApplied=!!effective&&(careerDirectionSelection[key]===undefined||careerDirectionSelection[key]===-1),full=wbValidate(useApplied?(effective.p.lanes[r]||effective.full):chosen.d),first=context!=='summary'&&context!=='救世篇',d=first?{...full,stages:wbSplitPlan(full).early}:full;return {d,full,r,custom:useApplied,directions,chosen,key,first};}

function wbDetailCalculation(c,plan){const result=wbCalculate(plan.d);result.rows=result.rows.map(row=>({...row,baselineKnown:result.baselineKnown}));if(!plan.custom||plan.first)return result;const effective=wbEffective(c,'summary'),fusion=effective&&wbFusion(effective.p);if(fusion?.continuation)return {...fusion.continuation,rows:[...result.rows.filter(row=>row.phase==='early'),...fusion.continuation.rows.map(row=>({...row,baselineKnown:fusion.continuation.baselineKnown}))],warnings:result.warnings,fusion:plan.r!=='common'};if(fusion?.stats)return {...result,stats:fusion.stats,level:fusion.level,fusion:true};return result;}

function wbInlineMarkup(c,i,s,row){return `<div class="inline-node-editor"><label>职业<select data-inline-field="classId">${DB.classes.filter(cl=>!wbDetailRoute(c).first||!wbThirdOnlyClass(cl,c)).map(cl=>`<option value="${cl.id}" ${cl.id===s.classId?'selected':''}>${esc(cl.cn)} · ${esc(cl.col_1)}</option>`).join('')}</select></label><label>结束等级<input data-inline-field="end" type="number" min="${row.start}" max="99" value="${row.end}"></label><label>选择理由<textarea data-inline-field="reason" maxlength="1500" rows="3" placeholder="${esc(wbReason(c,{...s,reason:''}))}">${esc(s.reason)}</textarea></label><div><button data-inline-apply>保存并应用</button><button data-inline-cancel>取消</button></div><div class="inline-status" role="status"></div></div>`;}
careerDiagram=function(c){const plan=wbDetailRoute(c),d=plan.d;if(!d.stages.length)return '<p class="muted">本角色按后期入队能力接续，请在第三部查看职业养成。</p>';const result=wbDetailCalculation(c,plan);return `<section class="dossier-route">${plan.directions.length>1?`<div class="career-direction-tabs" role="group" aria-label="职业养成方向">${wbEffective(c)?`<button data-career-direction="-1" data-career-character="${c.id}" aria-pressed="${plan.custom}">已应用自定义</button>`:''}${plan.directions.map((p,i)=>`<button data-career-direction="${i}" data-career-character="${c.id}" aria-pressed="${!plan.custom&&plan.chosen===p}">${esc(p.name)}</button>`).join('')}</div>`:''}${!plan.custom&&plan.chosen.when?`<p class="career-direction-note">${esc(plan.chosen.when)} <span>${esc(plan.chosen.stop)}</span>${plan.chosen.source?` <a href="${escapeAttr(plan.chosen.source)}" target="_blank" rel="noopener">依据 ↗</a>`:''}</p>`:''}<div class="wb-path-heading"><span>${plan.custom?'已应用自定义路线':plan.first?wbRouteName(plan.r)+' · 融合前培养':'第三部 · 后续养成'}</span><small class="wb-path-level">终点参考等级 ${esc(wbClass(d.stages[d.stages.length-1].classId).col_31||'—')}</small><a href="#calculator" data-wb-character-entry="${c.id}" data-wb-route-entry="${plan.r}">完整养成计算 ↗</a></div><div class="career-graph-scroll"><ol class="dossier-timeline">${d.stages.map((s,i)=>{const cl=wbClass(s.classId),row=result.rows[i];return `<li class="${i===d.stages.length-1?'dossier-end-node':''}"><div class="dossier-node-stage"><span>${s.phase==='third'?'第三部':cl.col_1.replace('基础职业','初始').replace('职业','')}</span><small>${row.start===row.end?'资格接续 · 不升级':`Lv.${row.start} → ${row.end}`}</small></div><button class="path-class" data-reference-type="class" data-reference-id="${cl.id}" data-route-node="${i}" data-route-character="${c.id}" data-route-key="${plan.r}">${classIcon(cl,32)}<span>${esc(cl.cn)}</span></button><p class="dossier-node-reason">${esc(wbReason(c,s))}</p>${i===d.stages.length-1?`<small class="dossier-node-mastery">熟练：${esc(cl.col_37||'未记录')}</small>`:''}${c.canChangeClass===false?'':`<button class="inline-edit-button" data-inline-edit="${i}" data-inline-character="${c.id}" data-inline-route="${plan.r}" aria-label="编辑${esc(cl.cn)}节点"><svg viewBox="0 0 24 24" width="14" height="14" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true"><path d="m16 3 5 5-12 12-6 1 1-6Z M14 5l5 5"/></svg></button>`}</li>`;}).join('')}</ol></div>${result.warnings?.length?`<p class="wb-caption dossier-warnings">${result.warnings.map(w=>esc(w)).join('；')}</p>`:''}<div class="route-final-stats"><small>${result.fusion?'融合与接续后 · ':''}Lv.${result.level} ${result.baselineKnown?'永久属性期望':'成长增量（起始面板待确认）'}</small>${statPanel(result.baselineKnown?result.stats:result.gains,Object.keys(statNames),1)}</div>${result.fusion?'<p class="wb-caption">融合前节点展示所选接续线；第三部属性按多线融合后续养计算。</p>':''}${plan.first?'<p class="wb-caption">后续职业在「第三部 · 整合」查看；图中等级为计算安排。</p>':'<p class="wb-caption">最上级职业：第三部第1区分通关后开放；部分需修复神殿并完成支线。神将另需专用道具。</p>'}</section>`;};
let nodeEditor=null,nodeEditorAnchor=null;
function closeNodeEditor(focus=false){const anchor=nodeEditorAnchor;nodeEditor?.remove();nodeEditor=null;nodeEditorAnchor=null;wbInline=null;if(anchor?.isConnected){anchor.setAttribute('aria-expanded','false');if(focus)anchor.focus({preventScroll:true});}}
function positionNodeEditor(){if(!nodeEditor)return;if(!nodeEditorAnchor?.isConnected||!characterOpen()){closeNodeEditor();return;}const a=nodeEditorAnchor.getBoundingClientRect(),p=nodeEditor.getBoundingClientRect(),w=document.documentElement.clientWidth,h=window.visualViewport?.height||window.innerHeight,pad=12;nodeEditor.style.left=Math.max(pad,Math.min(a.left-20,w-p.width-pad))+'px';nodeEditor.style.top=Math.max(pad,Math.min(a.bottom+p.height+8<h?a.bottom+8:a.top-p.height-8,h-p.height-pad))+'px';}
function openNodeEditor(anchor){closeNodeEditor();closeClassQuick();const c=DB.characters.find(c=>c.id===anchor.dataset.inlineCharacter),plan=wbDetailRoute(c),i=Number(anchor.dataset.inlineEdit),d=wbValidate(plan.full),row=wbDetailCalculation(c,plan).rows[i];wbInline={characterId:c.id,r:plan.r,i,d,rowStart:row.start};nodeEditorAnchor=anchor;nodeEditor=document.createElement('section');nodeEditor.className='route-node-popover';nodeEditor.setAttribute('role','dialog');nodeEditor.setAttribute('aria-label','编辑'+wbClass(d.stages[i].classId).cn+'节点');nodeEditor.innerHTML=`<div class="node-editor-heading"><b>编辑职业节点</b><button data-inline-cancel aria-label="关闭节点编辑"><svg viewBox="0 0 24 24" width="18" height="18" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true"><path d="m6 6 12 12M18 6 6 18"/></svg></button></div>`+wbInlineMarkup(c,i,d.stages[i],row);document.querySelector('#characterPage').appendChild(nodeEditor);anchor.setAttribute('aria-expanded','true');positionNodeEditor();nodeEditor.querySelector('select').focus({preventScroll:true});}
document.addEventListener('keydown',e=>{if(nodeEditor&&e.key==='Escape'){e.preventDefault();e.stopImmediatePropagation();closeNodeEditor(true);}},true);
document.addEventListener('pointerdown',e=>{if(nodeEditor&&!nodeEditor.contains(e.target)&&!e.target.closest('[data-inline-edit]'))closeNodeEditor();},true);
document.addEventListener('scroll',e=>{if(nodeEditor&&!nodeEditor.contains(e.target))positionNodeEditor();},true);
document.addEventListener('close',e=>{if(e.target.id==='detail')closeNodeEditor();},true);
window.addEventListener('resize',positionNodeEditor);

function wbNodeHover(trigger){if(trigger.dataset.routeNode===undefined)return '';const c=DB.characters.find(c=>c.id===trigger.dataset.routeCharacter),plan=wbDetailRoute(c),i=Number(trigger.dataset.routeNode),row=wbDetailCalculation(c,plan).rows[i],s=plan.d.stages[i];return `<p><b>选择理由：</b>${esc(wbReason(c,s))}</p><small>Lv.${row.end} ${(row.baselineKnown??plan.d.baselineKnown)?'永久属性期望':'成长增量（起始面板待确认）'}</small>${statPanel((row.baselineKnown??plan.d.baselineKnown)?row.stats:row.gains,Object.keys(statNames),1)}`;}
const originalClassQuickHTML=classQuickHTML;
classQuickHTML=function(cl){return originalClassQuickHTML(cl)+(classHoverTrigger?wbNodeHover(classHoverTrigger):'');};
document.addEventListener('click',e=>{const edit=e.target.closest('[data-inline-edit]');if(edit){openNodeEditor(edit);return;}if(e.target.closest('[data-inline-cancel]')){closeNodeEditor(true);return;}if(e.target.closest('[data-inline-apply]')&&wbInline){const editor=e.target.closest('.inline-node-editor'),edit=wbInline,c=DB.characters.find(c=>c.id===edit.characterId),d=wbValidate(edit.d),s=d.stages[edit.i],row=wbCalculate(d).rows[edit.i];const classId=editor.querySelector('[data-inline-field="classId"]').value;if(s.classId!==classId)s.pet='';s.classId=classId;s.levels=Math.floor(wbNumber(editor.querySelector('[data-inline-field="end"]').value,edit.rowStart??row.start,99))-(edit.rowStart??row.start);s.reason=editor.querySelector('[data-inline-field="reason"]').value;const old=wbEffective(c,'summary')?.p;let p=old?wbProjectValidate(old):{version:2,characterId:c.id,name:c.cn+'自定义方案',activeRoute:edit.r,lanes:{},selected:[]};p.lanes[edit.r]=d;p.activeRoute=edit.r;if(!p.selected.includes(edit.r))p.selected.push(edit.r);if(!wbSaveApply(p)){editor.querySelector('.inline-status').textContent=wbLastError||'浏览器未能保存，请重试或导出方案。';return;}careerDirectionSelection[c.id]=-1;if(wbProjects[c.id])wbProjects[c.id].lanes[edit.r]=wbValidate(d);delete selectedClasses[c.id];closeNodeEditor();openCharacter(c.id,true);wbPersist();return;}});
const originalWorkbenchEditor=wbEditor;
wbEditor=function(){return originalWorkbenchEditor()+`<div class="wb-apply-state">${wbApplied[wbCharacter]?'<span>已应用的方案继续生效；当前改动为草稿。</span><button data-wb-unapply>恢复攻略推荐</button>':'<span>尚未应用自定义方案；攻略继续使用默认推荐。</span>'}</div>`;};
document.addEventListener('click',e=>{if(!e.target.closest('[data-wb-unapply]'))return;const old=wbApplied[wbCharacter];delete wbApplied[wbCharacter];if(!wbPersist()){wbApplied[wbCharacter]=old;wbStatus('浏览器未能保存，请重试。');return;}wbUpdate(true);wbStatus('已恢复攻略推荐，保存的方案仍可读取。');});
// Skills keep their source, character, profession and acquisition relationships.
function abilityBy(id){return CATALOG.abilities.find(a=>a.id===id)||CATALOG.abilities.find(a=>a.name===id);}
function abilityName(name,type){return CATALOG.abilities.find(a=>a.name===name&&a.type===type)||CATALOG.abilities.find(a=>a.name===name);}
function abilityCondition(a){return [a.method,a.level!=null?'Lv.'+a.level:'',a.skill,a.rank,a.condition,a.uncertain?'获取条件待核实':''].filter(Boolean).join(' · ');}
function abilityCharacters(a){return a.characters.map(id=>DB.characters.find(c=>c.id===id)).filter(Boolean);}
function abilityUsableClasses(a){return (a.usableClasses||[]).map(id=>wbClass(id)).filter(Boolean);}
function abilityClasses(a){return a.classes.map(id=>wbClass(id)).filter(Boolean);}
function abilityDetails(a){return `<div class="source-dialog-head"><h2 id="source-dialog-title">${esc(a.name)}</h2><p>${esc(a.type)}</p></div><div class="reference-facts">${[...new Set(a.descriptions.map(d=>d.text))].map(text=>`<p>${esc(text)}</p>`).join('')}${abilityUsableClasses(a).length?`<h3>可用职业权限</h3><p class="muted">按该技能所需武器／魔术权限匹配；能使用不代表该角色已经习得。</p><div class="segments">${abilityUsableClasses(a).map(cl=>referenceLink('class',cl.id,cl.cn)).join('')}</div>`:''}<h3>获取途径与关联资料</h3><div class="ability-bindings">${a.acquisition.map(b=>{const c=DB.characters.find(c=>c.id===b.characterId),cl=wbClass(b.classId);return `<div>${c?`<button class="ability-person" data-char="${c.id}">${portrait(c)}<b>${esc(c.cn)}</b></button>`:cl?referenceLink('class',cl.id,cl.cn):''}<p>${esc(abilityCondition(b))}</p>${b.description?`<small>${esc(b.description)}</small>`:''}${[...new Set(b.sources?.length?b.sources:[b.source].filter(Boolean))].map((u,i)=>`<a href="${escapeAttr(u)}" target="_blank" rel="noopener">资料来源${i+1} ↗</a>`).join(' · ')}</div>`;}).join('')}</div></div>`;}
const originalReferenceMarkup=referenceMarkup;
referenceMarkup=function(type,id){if(type==='ability'){const a=abilityBy(id);return a?abilityDetails(a):'';}return originalReferenceMarkup(type,id);};
let abilityKind='all',abilityLimit=30,abilityQuery='';
pages.skills='特技与战技';
function skillDatabasePage(){if(abilityQuery!==query){abilityLimit=30;abilityQuery=query;}const q=query.toLowerCase(),all=CATALOG.abilities.filter(a=>(abilityKind==='all'||a.type===abilityKind)&&[a.name,...a.descriptions.map(d=>d.text),...abilityCharacters(a).map(c=>c.cn),...abilityClasses(a).map(c=>c.cn),...abilityUsableClasses(a).map(c=>c.cn),...a.acquisition.map(abilityCondition)].join(' ').toLowerCase().includes(q)),types=[...new Set(CATALOG.abilities.map(a=>a.type))];return `<div class="page-title"><h1>特技与战技</h1><p>${CATALOG.abilities.length}项特技、战技、个人技能与法术，关联角色、职业和获取条件；未核实条件单独标注。</p></div>${filterDeck(toolbar('搜索特技、战技、角色或获取条件…',searchCount(all.length,CATALOG.abilities.length,'项')),[['类型',`<div class="segments">${['all',...types].map(type=>`<button data-ability-kind="${type}" class="${abilityKind===type?'active':''}">${type==='all'?'全部':esc(type)} <span>${type==='all'?CATALOG.abilities.length:CATALOG.abilities.filter(a=>a.type===type).length}</span></button>`).join('')}</div>`]])}<div class="table-wrap ability-table"><table><thead><tr><th>技能</th><th>效果</th><th>获取途径</th><th>关联角色／职业</th></tr></thead><tbody>${all.slice(0,abilityLimit).map(a=>`<tr><td><button class="reference-link" data-reference-type="ability" data-reference-id="${a.id}"><b>${esc(a.name)}</b></button><small>${esc(a.type)}</small></td><td data-skill-images="off">${esc(a.descriptions[0]?.text||'效果未收录')}${new Set(a.descriptions.map(d=>d.text)).size>1?'<small>存在不同记载，悬停或查看完整条目。</small>':''}</td><td>${[...new Set(a.acquisition.map(abilityCondition))].slice(0,2).map(t=>`<small>${esc(t)}</small>`).join('')}${a.acquisition.length>2?`<small>共${a.acquisition.length}条关联记录</small>`:''}</td><td>${abilityCharacters(a).length?peopleStack(abilityCharacters(a).map(c=>({id:c.id,stage:'可习得'})),{max:5,label:a.name}).replace(/<small class="people-summary">[^<]*<\/small>/,`<small class="people-summary">${abilityCharacters(a).length}名角色${abilityUsableClasses(a).length?` · ${abilityUsableClasses(a).length}种职业可用`:''}</small>`):(abilityUsableClasses(a).length?`<small class="muted">${abilityUsableClasses(a).length}种职业可用</small>`:'')}${abilityClasses(a).length?`<div class="ability-class-links">${abilityClasses(a).slice(0,3).map(c=>referenceLink('class',c.id,c.cn)).join('')}</div>`:''}</td></tr>`).join('')||'<tr><td colspan="4">没有匹配技能，请调整搜索或分类。</td></tr>'}</tbody></table></div>${all.length>abilityLimit?'<button data-abilities-more>继续显示30项</button>':''}`;}
document.addEventListener('click',e=>{const kind=e.target.closest('[data-ability-kind]');if(kind){abilityKind=kind.dataset.abilityKind;abilityLimit=30;render();}if(e.target.closest('[data-abilities-more]')){abilityLimit+=30;const scroll=window.scrollY;render();window.scrollTo(0,scroll);}if(e.target.closest('.ability-person[data-char]')&&$('#sourceDialog').open)$('#sourceDialog').close();});
actionChips=function(c,compact=false){const r=recommendations(c),chip=(a,type)=>{const skill=abilityName(a.name,{art:'战技',magic:'法术',skill:'特技'}[type]);return `<button class="action-chip ${type}-chip" ${skill?`data-reference-type="ability" data-reference-id="${skill.id}"`:''}>${esc(a.name)}${compact?'':`<em>${esc(a.rank||(a.level?'Lv'+a.level:'条件'))}</em>`}</button>`;},row=(name,items,type)=>`<div class="${compact?'loadout-row':'action-row'}"><small>${name}</small><div class="chip-list">${items.length?items.map(a=>chip(a,type)).join(''):'<span class="muted">普通攻击、恢复或法术为主</span>'}</div></div>`;return `<div class="action-chips ${compact?'compact-actions':''}">${row(compact?'战技':`战技 ${r.arts.length}/${r.slots}`,r.arts,'art')}${r.magic.length?row('法术',r.magic,'magic'):''}${row(compact?'特技':`特技 ${r.skills.length}/5`,r.skills,'skill')}</div>`;};
function quickAbilityBindings(a){const id=classHoverTrigger?.closest('.char-card')?.dataset.char||(classHoverTrigger?.closest('#characterPage')?activeCharacter:null),matches=id?a.acquisition.filter(b=>b.characterId===id):[];return matches.length?matches:a.acquisition;}
function quickReferenceHTML(type,id){if(type==='class')return classQuickHTML(wbClass(id));if(type==='equipment'){const e=EQUIPMENT.find(x=>x.id===id);if(!e)return '';return `<div class="class-quick-head"><b>${equipmentIcon(e)} ${esc(e.name)}</b><button data-class-quick-close aria-label="关闭装备速览"><svg viewBox="0 0 24 24" width="18" height="18" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true"><path d="m6 6 12 12M18 6 6 18"/></svg></button></div><small>${esc(e.type)} · ${esc(e.rank)}</small><dl class="weapon-stat-grid">${equipmentMetrics(e).slice(0,6).map(([,label,value])=>`<div><dt>${label}</dt><dd>${value}</dd></div>`).join('')}</dl><p>${esc(e.effect)}</p><p>${esc(e.purpose)}</p><small>${esc(e.sourcesList.slice(0,3).map(s=>[s.place,s.kind].filter(Boolean).join(' · ')).join('；'))}</small><button class="text-button" data-quick-full="${e.id}" data-quick-type="equipment">完整资料与获取途径 ↗</button>`;}const a=abilityBy(id);if(!a)return '';return `<div class="class-quick-head"><b>${esc(a.name)}</b><button data-class-quick-close aria-label="关闭技能速览"><svg viewBox="0 0 24 24" width="18" height="18" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true"><path d="m6 6 12 12M18 6 6 18"/></svg></button></div><small>${esc(a.type)}</small><p>${esc(a.descriptions[0]?.text||'效果未收录')}</p>${[...new Set(quickAbilityBindings(a).map(abilityCondition))].slice(0,4).map(t=>`<p class="quick-acquisition">${esc(t)}</p>`).join('')}<small>${esc(abilityCharacters(a).slice(0,8).map(c=>c.cn).join('、'))}${a.characters.length>8?' 等':''}${abilityClasses(a).length?' · '+esc(abilityClasses(a).map(c=>c.cn).join('、')):''}</small><button class="text-button" data-quick-full="${a.id}" data-quick-type="ability">完整资料与全部获取途径 ↗</button>`;}
classQuickTrigger=function(t){return t.closest?.('[data-reference-type="class"],button[data-reference-type="equipment"],button[data-reference-type="ability"]');};
openClassQuick=function(trigger){clearTimeout(classHoverTimer);if(classHoverTrigger===trigger&&classHover)return;closeClassQuick();classHoverTrigger=trigger;const type=trigger.dataset.referenceType,html=quickReferenceHTML(type,trigger.dataset.referenceId);if(!html){classHoverTrigger=null;return;}classHover=document.createElement('section');classHover.id='class-quick-preview';classHover.className='class-quick-preview';classHover.setAttribute('role','region');classHover.setAttribute('aria-label','资料速览');classHover.innerHTML=html;(document.querySelector('#sourceDialog[open]')||document.querySelector('#detail[open]')||document.body).appendChild(classHover);trigger.removeAttribute('title');trigger.setAttribute('aria-expanded','true');trigger.setAttribute('aria-describedby',classHover.id);positionClassQuick();};
document.addEventListener('click',e=>{const full=e.target.closest('[data-quick-full]');if(full){const type=full.dataset.quickType,id=full.dataset.quickFull;closeClassQuick();openReferenceDialog(type,id);e.stopImmediatePropagation();}},true);
// Apply the final class's permissions to equipment suggestions for custom plans.
const originalEquipmentEntries=equipmentEntries;
// Default suggestions follow each character's audited gear plan (exclusives and guide picks first), filtered by the career in view.
function gearPlanEntries(cs){const map=new Map(),skillOf={剑:'剑术',枪:'枪术',斧:'斧术',弓:'弓术',拳:'格斗术',手甲:'格斗术'};for(const c of cs){const picks=c.gearPlan?.picks;if(!picks){for(const x of originalEquipmentEntries([c])){if(!map.has(x.e.id))map.set(x.e.id,{e:x.e,users:[]});map.get(x.e.id).users.push(c);}continue;}const b=buildPlan(c),r=routeContext(c),cl=classBy(r==='summary'?b.end.split(' / ')[0]:b.upper[0]),allowed=new Set(cl?.allowedSkills||[]);for(const p of picks){if(r!=='summary'&&p.kind==='late')continue;const e=EQUIPMENT.find(e=>e.id===p.id);if(!e)continue;const need=skillOf[e.type];if(need&&allowed.size&&!allowed.has(need))continue;if(!map.has(e.id))map.set(e.id,{e,users:[]});map.get(e.id).users.push(c);}}return [...map.values()];}
equipmentEntries=function(cs,allOptions=false){if(allOptions)return originalEquipmentEntries(cs,true);const defaults=cs.filter(c=>!wbEffective(c)),out=gearPlanEntries(defaults),map=new Map(out.map(x=>[x.e.id,x]));for(const c of cs.filter(c=>wbEffective(c))){const cl=wbClass(wbRecommendedClass(c,routeContext(c))),allowed=new Set(cl.allowedSkills),ids=[];for(const [skill,id]of [['剑术','daminasword'],['枪术','aurora_lance'],['斧术','daminaaxe'],['弓术','damina_bow'],['格斗术','daminafist'],['白魔术','heal'],['黑魔术','magic_staff']])if(allowed.has(skill))ids.push(id);for(const id of ids){const e=EQUIPMENT.find(e=>e.id===id);if(!e)continue;if(!map.has(id))map.set(id,{e,users:[]});map.get(id).users.push(c);}}return [...map.values()];};
if(DB)render();

document.addEventListener('click',e=>{const b=e.target.closest('[data-career-direction]');if(!b)return;const c=DB.characters.find(c=>c.id===b.dataset.careerCharacter);careerDirectionSelection[c.id]=Number(b.dataset.careerDirection);closeNodeEditor();openCharacter(c.id,true);});

// Reuse the avatar + aligned content rows for route planning; dance is a direction in dossiers.
preferencePlan=function(){const chosen=DB.characters.filter(c=>isPreferred(c)&&Object.keys(CATALOG.planning[c.id].routes).length),rs=Object.keys(routes).filter(r=>r!=='救世篇');return `<h2>跨线互补培养</h2>${crossRoutePolicyPanel()}<div class="plan-rows">${chosen.map(c=>`<article>${tableCharacter(c,{subtitle:finalBuild(c).end,showRating:false})}<div class="plan-row-routes">${rs.map(r=>{const p=trainingProfiles(c)[r],b=buildPlan(c,r);return `<div><b>${routeIdentity(r)}</b>${p?`<small>${esc(p.optional?'补修 · '+p.label:p.label)}</small>${complementStages(c,b)}`:'<small>本线不安排培养</small>'}</div>`;}).join('')}</div></article>`).join('')}</div>`;};
thirdPartPlanning=function(){return reviewedThirdPartPlanning();};

const originalDirectionOpen=wbOpen;
wbOpen=function(id,r,node){const c=DB.characters.find(c=>c.id===id);if(c&&characterOpen()&&activeCharacter===id&&careerDirectionSelection[id]!==undefined&&careerDirectionSelection[id]>=0){const plan=wbDetailRoute(c),p=wbProject(id);wbRemember(p);p.lanes[plan.r]=wbValidate(plan.full);p.activeRoute=plan.r;if(!p.selected.includes(plan.r))p.selected.push(plan.r);wbDraft=p.lanes[plan.r];}return originalDirectionOpen(id,r,node);};
