const reviewedSourceConflictReview=sourceConflictReview;
sourceConflictReview=function(){const a=CATALOG.dataResearch,n=a.remainingCounts;return `<p class="research-summary">本轮核对：63名角色、60种职业、147件装备。已补齐学习资料中的效果说明；仍有${n.skillRequirements}条习得门槛、${n.skillProvenance}条来源归类待核实，${n.basePanels}名角色缺少可靠起始面板。空白项不按其他角色或成长率推算。</p>`+reviewedSourceConflictReview()+`<details><summary>本轮补充资料的来源</summary><div class="source-directory">${(a.latestSources||[]).map(u=>`<a href="${escapeAttr(u)}" target="_blank" rel="noopener">${esc(u.split('/')[2])} ↗</a>`).join('')}<a href="research/learning-evidence.html" target="_blank" rel="noopener">离线攻略条件核对记录 ↗</a></div></details>`;};
